def subarray_sum(nums, k):
    count = 0
    prefix_sum = 0
    freq = {0: 1}
    for value in nums:
        prefix_sum += value
        count += freq.get(prefix_sum - k, 0)
        freq[prefix_sum] = freq.get(prefix_sum, 0) + 1
    return count
